function maximum(a) {
  if (!Array.isArray(a) ||
      !Array.from(a).every(Number.isSafeInteger)) {
    throw new TypeError("Use an array of safe integers");
  }
  if (a.length === 0) throw new RangeError("No maximum of an empty list");
  let best = a[0];
  for (let i = 1; i < a.length; i++) {
    if (a[i] > best) best = a[i];
  }
  return best;
}

function linearSearch(a, x) {
  if (!Array.isArray(a) ||
      !Array.from(a).every(Number.isSafeInteger)) {
    throw new TypeError("Use an array of safe integers");
  }
  if (!Number.isSafeInteger(x)) throw new TypeError("Use an integer target");
  for (let i = 0; i < a.length; i++) {
    if (a[i] === x) return i + 1;
  }
  return 0;
}

function binarySearch(a, x) {
  if (!Array.isArray(a) ||
      !Array.from(a).every(Number.isSafeInteger)) {
    throw new TypeError("Use an array of safe integers");
  }
  if (!Number.isSafeInteger(x)) throw new TypeError("Use an integer target");
  for (let i = 1; i < a.length; i++) {
    if (a[i] < a[i - 1]) throw new RangeError("Sort the input first");
  }
  if (a.length === 0) return 0;
  let lo = 0, hi = a.length - 1;
  while (lo < hi) {
    const mid = lo + Math.floor((hi - lo) / 2);
    if (x > a[mid]) lo = mid + 1;
    else hi = mid;
  }
  return a[lo] === x ? lo + 1 : 0;
}

function bubbleSort(a) {
  if (!Array.isArray(a) ||
      !Array.from(a).every(Number.isSafeInteger)) {
    throw new TypeError("Use an array of safe integers");
  }
  const b = a.slice();
  for (let end = b.length - 1; end > 0; end--) {
    for (let j = 0; j < end; j++) {
      if (b[j] > b[j + 1]) {
        [b[j], b[j + 1]] = [b[j + 1], b[j]];
      }
    }
  }
  return b;
}

function insertionSort(a) {
  if (!Array.isArray(a) ||
      !Array.from(a).every(Number.isSafeInteger)) {
    throw new TypeError("Use an array of safe integers");
  }
  const b = a.slice();
  for (let j = 1; j < b.length; j++) {
    const value = b[j];
    let i = 0;
    while (i < j && value > b[i]) i++;
    for (let k = j; k > i; k--) b[k] = b[k - 1];
    b[i] = value;
  }
  return b;
}

function matchShifts(text, pattern) {
  if (typeof text !== "string" || typeof pattern !== "string" ||
      !/^[01]*$/.test(text) || !/^[01]+$/.test(pattern)) {
    throw new TypeError("Use binary text and a nonempty binary pattern");
  }
  const shifts = [];
  for (let s = 0; s <= text.length - pattern.length; s++) {
    let j = 0;
    while (j < pattern.length && text[s + j] === pattern[j]) j++;
    if (j === pattern.length) shifts.push(s);
  }
  return shifts;
}

function greedyChange(n, coins) {
  if (!Number.isSafeInteger(n) || n < 0 ||
      !Array.isArray(coins) || coins.length === 0 ||
      !Array.from(coins).every(c => Number.isSafeInteger(c) && c > 0)) {
    throw new TypeError("Use a nonnegative amount and positive integer coins");
  }
  for (let i = 1; i < coins.length; i++) {
    if (coins[i] >= coins[i - 1]) throw new RangeError("Coins must strictly decrease");
  }
  let remainder = n;
  const counts = coins.map(c => {
    let count = 0;
    while (remainder >= c) { remainder -= c; count++; }
    return count;
  });
  return {counts, remainder};
}

function scheduleTalks(talks) {
  if (!Array.isArray(talks)) throw new TypeError("Use an array of intervals");
  const sorted = Array.from(talks, (t, id) => {
    if (!t || !Number.isSafeInteger(t.start) ||
        !Number.isSafeInteger(t.end) || t.start >= t.end) {
      throw new TypeError("Each interval needs integer start < end");
    }
    return {start: t.start, end: t.end, id};
  }).sort((a, b) => a.end - b.end || a.id - b.id);
  const selected = [];
  let lastEnd = -Infinity;
  for (const t of sorted) {
    if (t.start >= lastEnd) {
      selected.push(t.id);
      lastEnd = t.end;
    }
  }
  return selected;
}
